<script setup>
import { computed,onMounted,reactive,ref,watch } from "vue";import{useRoute}from"vue-router";import{call}from"../api";
const route=useRoute(),loading=ref(true),error=ref(""),data=reactive({}),options=reactive({entities:[],points:[],groups:[]});const filters=reactive({month:new Date().toISOString().slice(0,7),from_date:new Date(new Date().getFullYear(),new Date().getMonth(),1).toISOString().slice(0,10),to_date:new Date().toISOString().slice(0,10),business_entity:"",business_point:"",catalog_group:"",search:""});
const kind=computed(()=>route.meta.kind||"report");const money=v=>`${new Intl.NumberFormat("ru-RU",{minimumFractionDigits:2,maximumFractionDigits:2}).format(Number(v||0))} ₽`;const percent=v=>`${new Intl.NumberFormat("ru-RU",{maximumFractionDigits:1}).format(Number(v||0))}%`;const points=computed(()=>options.points.filter(x=>!filters.business_entity||x.business_entity===filters.business_entity));
const heading=computed(()=>({overview:["Финансовый обзор","Главные показатели компании за текущий месяц"],report:["Финансовый отчёт","ДДС, ОПиУ, баланс и план-факт на одной странице"],settlements:["Взаиморасчёты","Поступления, выплаты и открытые обязательства по контрагентам"],profitability:["Прибыльность","Выручка, себестоимость и прибыль по товарам и услугам"]}[kind.value]));
async function load(){loading.value=true;error.value="";try{let method="get_financial_report",params={month:`${filters.month}-01`,business_entity:filters.business_entity,business_point:filters.business_point};if(kind.value==="settlements"){method="get_settlements";params={from_date:filters.from_date,to_date:filters.to_date,business_entity:filters.business_entity,business_point:filters.business_point,search:filters.search};}if(kind.value==="profitability"){method="get_profitability";params={from_date:filters.from_date,to_date:filters.to_date,business_entity:filters.business_entity,business_point:filters.business_point,catalog_group:filters.catalog_group,search:filters.search};}Object.assign(data,await call(`raspechatka.api.finance.${method}`,params));}catch(e){error.value=e.message;}finally{loading.value=false;}}
async function init(){const o=await call("raspechatka.api.finance.get_finance_options");Object.assign(options,o);options.groups=await call("raspechatka.api.frontend.get_catalog_filters").then(x=>x.groups);await load();}watch(kind,load);onMounted(init);
</script>
<template><section class="page finance-page"><div class="page-heading"><div><div class="eyebrow">ФИНАНСЫ / ОТЧЁТЫ</div><h1>{{heading[0]}}</h1><p>{{heading[1]}}</p></div></div><div class="finance-toolbar report-filter"><template v-if="kind==='report'||kind==='overview'"><input v-model="filters.month" type="month" @change="load"/></template><template v-else><label class="search-field"><span>⌕</span><input v-model="filters.search" placeholder="Поиск" @input="load"/></label><input v-model="filters.from_date" type="date" @change="load"/><input v-model="filters.to_date" type="date" @change="load"/></template><select v-model="filters.business_entity" @change="filters.business_point='';load()"><option value="">Все ИП</option><option v-for="x in options.entities" :key="x.name" :value="x.name">{{x.short_name}}</option></select><select v-model="filters.business_point" @change="load"><option value="">Все точки</option><option v-for="x in points" :key="x.name" :value="x.name">{{x.point_name}}</option></select><select v-if="kind==='profitability'" v-model="filters.catalog_group" @change="load"><option value="">Все группы</option><option v-for="x in options.groups" :key="x.name" :value="x.name">{{x.group_name}}</option></select></div><div v-if="loading" class="table-message"><span class="loader"></span><span>Рассчитываем показатели…</span></div><div v-else-if="error" class="table-message error-message"><strong>Не удалось сформировать отчёт</strong><span>{{error}}</span><button @click="load">Повторить</button></div>
<template v-else-if="kind==='report'||kind==='overview'"><div class="finance-kpis"><article class="accent"><small>ВЫРУЧКА</small><b>{{money(data.pnl?.revenue)}}</b><span>план {{money(data.plan_fact?.revenue_plan)}} · {{percent(data.plan_fact?.revenue_attainment)}}</span></article><article><small>РАСХОДЫ</small><b>{{money(data.pnl?.expenses)}}</b><span>по проведённым платежам</span></article><article><small>ЧИСТАЯ ПРИБЫЛЬ</small><b>{{money(data.pnl?.net_profit)}}</b><span>рентабельность {{percent(data.pnl?.margin)}}</span></article><article><small>ДЕНЬГИ НА КОНЕЦ</small><b>{{money(data.cash_flow?.closing_cash)}}</b><span>чистый поток {{money(data.cash_flow?.net_cash_flow)}}</span></article></div><div class="finance-report-grid"><article class="finance-panel"><header><small>ОПиУ</small><h2>Доходы и расходы</h2></header><div class="statement-row"><span>Выручка</span><b>{{money(data.pnl?.revenue)}}</b></div><div class="statement-row"><span>Расходы</span><b>−{{money(data.pnl?.expenses)}}</b></div><div class="statement-row total"><span>Чистая прибыль</span><b>{{money(data.pnl?.net_profit)}}</b></div><div v-for="row in data.articles" :key="row.article" class="statement-row detail"><span>{{row.article_name}}</span><span>{{money(row.actual)}}</span></div></article><article class="finance-panel"><header><small>ДДС</small><h2>Движение денег</h2></header><div class="statement-row"><span>Деньги на начало</span><b>{{money(data.cash_flow?.opening_cash)}}</b></div><div v-for="(row,key) in data.cash_flow?.sections" :key="key" class="statement-row"><span>{{key==='Operating'?'Операционная деятельность':key==='Investing'?'Инвестиции':'Финансирование'}}</span><b>{{money(row.net)}}</b></div><div class="statement-row total"><span>Деньги на конец</span><b>{{money(data.cash_flow?.closing_cash)}}</b></div></article><article class="finance-panel"><header><small>БАЛАНС</small><h2>Финансовая позиция</h2></header><div class="statement-row"><span>Деньги</span><b>{{money(data.balance?.cash)}}</b></div><div class="statement-row"><span>Запасы</span><b>{{money(data.balance?.inventory)}}</b></div><div class="statement-row"><span>Оборудование</span><b>{{money(data.balance?.equipment)}}</b></div><div class="statement-row"><span>Обязательства</span><b>−{{money(data.balance?.liabilities)}}</b></div><div class="statement-row total"><span>Чистая позиция</span><b>{{money(data.balance?.net_position)}}</b></div></article></div></template>
<template v-else><div v-if="kind==='profitability'&&!data.source_ready" class="integration-note"><b>Отчёт готов к данным кассы</b><span>Структура расчёта уже создана. Строки появятся автоматически после подключения продаж: выручка − возвраты − скидки − себестоимость.</span></div><div class="table-shell"><div v-if="!data.rows?.length" class="table-message"><strong>Данных пока нет</strong><span>Измените период или добавьте связанные операции.</span></div><table v-else-if="kind==='settlements'"><thead><tr><th>Контрагент</th><th>Тип</th><th>Приход</th><th>Расход</th><th>Баланс</th><th>К получению</th><th>К оплате</th></tr></thead><tbody><tr v-for="r in data.rows" :key="r.counterparty"><td class="item-name">{{r.counterparty}}</td><td>{{r.counterparty_type}}</td><td class="number-cell positive">{{money(r.income)}}</td><td class="number-cell">{{money(r.expense)}}</td><td class="number-cell">{{money(r.balance)}}</td><td class="number-cell">{{money(r.receivable)}}</td><td class="number-cell">{{money(r.payable)}}</td></tr></tbody></table><table v-else><thead><tr><th>Наименование</th><th>Документы</th><th>Количество</th><th>Выручка</th><th>Себестоимость</th><th>Возвраты</th><th>Скидки</th><th>Рентабельность</th><th>Прибыль</th></tr></thead><tbody><tr v-for="r in data.rows" :key="r.item"><td class="item-name">{{r.item_name}}</td><td>{{r.documents}}</td><td>{{r.quantity}}</td><td class="number-cell">{{money(r.revenue)}}</td><td class="number-cell">{{money(r.cost)}}</td><td class="number-cell">{{money(r.returns)}}</td><td class="number-cell">{{money(r.discounts)}}</td><td class="number-cell">{{percent(r.margin)}}</td><td class="number-cell positive">{{money(r.profit)}}</td></tr></tbody></table></div></template></section></template>
